<?php
require __DIR__.'/common.php'; method('POST'); $user=uid();$b=json_decode(file_get_contents('php://input'),true)?:[];$plan=$b['plan']??'';if(!isset($config['plans'][$plan]))out(400,['error'=>'invalid_plan']);$p=$config['plans'][$plan];$id='ix_'.bin2hex(random_bytes(12));$phone=preg_replace('/\\D/','',$b['phone']??'');$payload=['order_id'=>$id,'order_amount'=>$p['amount'],'order_currency'=>$p['currency'],'customer_details'=>['customer_id'=>substr(hash('sha256',$user),0,30),'customer_phone'=>$phone ?: '9999999999'],'order_meta'=>['return_url'=>$config['return_url'].'?order_id='.$id]];$created=cf('POST','/orders',$payload);db()->prepare('INSERT INTO orders(order_id,user_id,plan,amount,currency,status,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$id,$user,$plan,$p['amount'],$p['currency'],'PENDING',gmdate('c')]);out(200,['order_id'=>$id,'payment_session_id'=>$created['payment_session_id']??null,'amount'=>$p['amount'],'currency'=>$p['currency'],'environment'=>$config['environment']]);
